#!/bin/bash
#================================================================================================
#	This script is for recreating *.ts files from LLM translated *.txt files.
#	Uses *.ts files generated by cmake only as templates, outputs somewhere else.
#	Edit the variables given at the top to your liking.
#================================================================================================
TSDir=../languages
InputDir=~/Desktop/languagesIN
OutputDir=~/Desktop/languagesTS
#================================================================================================

mkdir -p "$OutputDir" || exit 1
log_file="$OutputDir/errors.log"
: > "$log_file"

shopt -s nullglob
txt_files=("$InputDir"/*.txt)

if (( ${#txt_files[@]} == 0 )); then
    printf 'No .txt files found in: %s\n' "$InputDir"
    exit 0
fi

for txt_file in "${txt_files[@]}"; do
    filename="${txt_file##*/}"
    basename="${filename%.txt}"
    ts_template="$TSDir/$basename.ts"
    out_ts="$OutputDir/$basename.ts"

    if [[ ! -f "$ts_template" ]]; then
        printf 'Missing template: %s\n' "$ts_template" | tee -a "$log_file"
        continue
    fi

    # Validate format: after the prompt header, expect repeating
    # <source>...<  then <translation>...<  then empty line
    # Skip first non-empty lines that do not start with <source>
    error=""
    mapfile -t lines < "$txt_file"

    # Find start of data (first <source> line)
    start=0
    for ((i=0; i<${#lines[@]}; i++)); do
        if [[ "${lines[i]}" == \<source\>* ]]; then
            start=$i
            break
        fi
    done

    translations=()
    i=$start
    while (( i < ${#lines[@]} )); do
        src="${lines[i]}"
        ((i++))
        if [[ -z "${lines[i]:-}" ]]; then
            error="Empty line where translation expected near line $((i+1))"
            break
        fi
        tr="${lines[i]}"
        ((i++))
        # Expect empty line (or end of file)
        if (( i < ${#lines[@]} )) && [[ -n "${lines[i]}" ]]; then
            error="Missing empty line after translation near line $((i+1))"
            break
        fi
        ((i++))  # skip empty

        if [[ "$src" != \<source\>*\< ]]; then
            error="Malformed source line: $src"
            break
        fi
        if [[ "$tr" != \<translation\>*\< ]]; then
            error="Malformed translation line: $tr"
            break
        fi

        # Extract content between <translation> and trailing <
        content="${tr#<translation>}"
        content="${content%<}"
        translations+=("$content")
    done

    if [[ -n "$error" ]]; then
        printf '%s: %s\n' "$filename" "$error" | tee -a "$log_file"
        continue
    fi

    # Reconstruct .ts by replacing <translation>...</translation> contents in order
    awk -v n="${#translations[@]}" '
        BEGIN {
            for (j=0; j<n; j++) {
                getline t < "/dev/stdin"
                trans[j] = t
            }
            idx = 0
        }
        /<translation([[:space:]>])/ {
            line = $0
            # Preserve attributes if any, replace only the content
            if (match(line, /<translation[^>]*>/)) {
                open = substr(line, RSTART, RLENGTH)
                rest = substr(line, RSTART+RLENGTH)
                sub(/<\/translation>.*/, "", rest)
                if (idx < n) {
                    print open trans[idx] "</translation>"
                    idx++
                } else {
                    print $0
                }
            } else {
                print $0
            }
            next
        }
        { print }
    ' < <(printf '%s\n' "${translations[@]}") "$ts_template" > "$out_ts"

    printf 'Created: %s\n' "$out_ts"
done

if [[ -s "$log_file" ]]; then
    printf 'Errors written to %s\n' "$log_file"
fi